const std = @import("std");
const CF = .{ .maxz = 65536, .micr = 1000000.0, .vend = @as([]const []const u8, &.{ "deco", "zenr", "brig" }), .mods = @as([]const []const u8, &.{ "purg", "upgr" }), .stor = @as([]const []const u8, &.{ "b2zz", "r2zz", "tigr" }), .sqlz = @as([]const []const u8, &.{ "turs", "neon", "tidb" }) };
pub const Vmap = struct { deco: u32 = 0, zenr: u32 = 0, brig: u32 = 0 };
pub const Endp = struct { hos4: []const u8 = "", regn: []const u8 = "auto", bukt: []const u8 = "", dbnm: []const u8 = "", usrz: []const u8 = "" };
pub const Emap = struct { b2zz: Endp = .{ .regn = "us-west-004" }, r2zz: Endp = .{}, tigr: Endp = .{ .hos4 = "t3.storage.dev" }, turs: Endp = .{}, neon: Endp = .{}, tidb: Endp = .{} };
pub const Gmap = struct { b2zz: u32 = 10, r2zz: u32 = 10, tigr: u32 = 5 };
pub const Conf = struct { clou_endp: Emap = .{}, clou_capz_gbyt: Gmap = .{}, clou_stor_orde: []const []const u8 = &.{ "b2zz", "r2zz", "tigr" }, clou_sqlz_orde: []const []const u8 = &.{ "turs", "neon", "tidb" }, clou_sync_batz: u32 = 200, aler_mail_toxx: []const u8 = "", aler_mail_from: []const u8 = "", revi_star_seco: u32 = 86400, revi_floo_seco: u32 = 3600, revi_capz_seco: u32 = 2592000, vend_free_cred: Vmap = .{}, vend_cred_micr: Vmap = .{ .deco = 1000, .zenr = 1000, .brig = 1000 }, vend_keyz_dirz: []const u8 = "~/.zz-base-home-secr/as-apps/ws-webs/sc-scra", vend_zone_brig: []const u8 = "", capz_usdz_mont: f64 = 0, capz_disk_gbyt: u32 = 5, clou_poli_mode: []const u8 = "purg", uagt_cont_mail: []const u8 = "", logi_mode_enab: bool = false, vend_orde: []const []const u8 = &.{ "deco", "zenr", "brig" }, fetc_time_seco: u32 = 30, fetc_body_maxz: u32 = 5242880, fetc_redi_maxz: u8 = 5, rate_host_seco: u32 = 1, retr_cont_maxz: u8 = 3, geoz_code_dflt: []const u8 = "", geoz_host_over: std.json.ArrayHashMap([]const u8) = .{}, shel_text_minz: u32 = 500, apiz_prob_enab: bool = true, apiz_prob_maxz: u32 = 8, pdfz_size_maxz: u32 = 20971520, brow_enab: bool = false, brow_path_exec: []const u8 = "", brow_prof_dirz: []const u8 = "~/.zs-scra-data/prof", brow_time_seco: u32 = 60, brow_scrl_maxz: u32 = 30, brow_step_maxz: u32 = 50, brow_head_mode: bool = false, cons_sele_list: []const []const u8 = &.{ "#onetrust-accept-btn-handler", "#didomi-notice-agree-button", "button.fc-cta-consent", "#cookiescript_accept", ".cc-allow", ".js-accept-cookies", "#accept-cookies", "button[aria-label*=\"Accept all\"]" }, strm_time_seco: u32 = 30, strm_frme_maxz: u32 = 1000, acct_page_maxz: u32 = 200, ocrz_path_exec: []const u8 = "", rate_jitt_pctz: u32 = 0, rate_429z_pctz: u32 = 100, retr_afte_enab: bool = true, retr_back_seco: u32 = 0, retr_code_list: []const u32 = &.{}, tier_star: []const u8 = "own", tier_maxz: u32 = 4, tier_skip_list: []const []const u8 = &.{}, tier_t1fz: u32 = 3, tier_ages: u32 = 7, vend_bann_list: []const []const u8 = &.{}, capz_cred_pagz: u32 = 0, apiz_path_list: []const []const u8 = &.{}, shel_mark_list: []const []const u8 = &.{}, judg_bloc_list: []const []const u8 = &.{}, judg_must_list: []const []const u8 = &.{}, judg_text_minz: u32 = 0, judg_fiel_requ: []const []const u8 = &.{}, brow_wait_msec: u32 = 0, brow_sele_wait: []const u8 = "", brow_clic_text: []const u8 = "", brow_step_file: []const u8 = "", brow_blok_resz: bool = false, acct_gapz_mult: u32 = 3, foll_maxz: u32 = 0, foll_incl_list: []const []const u8 = &.{}, foll_excl_list: []const []const u8 = &.{}, extr_pref_list: []const []const u8 = &.{ "ldjs", "next", "text" }, ocrz_enab: bool = true, grup_rule_mapz: ?std.json.Value = null, site_rule_list: ?std.json.Value = null, data_dirz_path: []const u8 = "~/.zs-scra-data" };
pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err3| { if (err3 == error.FileNotFound) return .{}; return err3; }; return confPars(allo, byte); }
pub fn confPars(allo: std.mem.Allocator, byte: []const u8) !Conf { const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if (!std.math.isFinite(conf.capz_usdz_mont) or conf.capz_usdz_mont < 0) return error.BadConfig; if (conf.capz_disk_gbyt == 0 or conf.fetc_time_seco == 0 or conf.fetc_body_maxz == 0 or conf.retr_cont_maxz == 0) return error.BadConfig; if (!inzzLisz(CF.mods, conf.clou_poli_mode)) return error.BadConfig; if (conf.vend_orde.len == 0 or conf.revi_floo_seco == 0 or conf.revi_floo_seco > conf.revi_capz_seco or conf.revi_star_seco < conf.revi_floo_seco or conf.revi_star_seco > conf.revi_capz_seco) return error.BadConfig; for (conf.vend_orde) |vend| if (!inzzLisz(CF.vend, vend)) return error.BadConfig; for (conf.clou_stor_orde) |item| if (!inzzLisz(CF.stor, item)) return error.BadConfig; for (conf.clou_sqlz_orde) |item| if (!inzzLisz(CF.sqlz, item)) return error.BadConfig; if (conf.clou_sync_batz == 0) return error.BadConfig; if (conf.geoz_code_dflt.len > 0 and !geozOkay(conf.geoz_code_dflt)) return error.BadConfig; var gite = conf.geoz_host_over.map.iterator(); while (gite.next()) |entr| if (!geozOkay(entr.value_ptr.*)) return error.BadConfig; }
fn geozOkay(code: []const u8) bool { return code.len == 2 and std.ascii.isAlphabetic(code[0]) and std.ascii.isAlphabetic(code[1]); }
fn inzzLisz(list: []const []const u8, item: []const u8) bool { for (list) |each| if (std.mem.eql(u8, each, item)) return true; return false; }
pub fn capzMicr(conf: Conf) u64 { return @intFromFloat(@round(conf.capz_usdz_mont * CF.micr)); }
